void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Reset variable activities to avoid stale bias
    for (int v = 1; v <= vars; ++v) {
        activity[v] = 0.0;
        if (!vsids.inHeap(v)) vsids.insert(v);
        else vsids.update(v);
    }
    var_inc = 1.0; // reset activity increment

    // Backtrack to root level
    backtrack(0);

    // Rephase variables with a new probability distribution
    int r = rand() % 100;
    if (r < 50) {
        // Use the best local assignment found so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 70) {
        // Use the opposite of the best local assignment
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // Random phase assignment
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}
